corpus_block("test-facet-strips.R: facet_wrap() builds correct output", {
  strip_layout <- function(p) {
    data <- ggplot_build(p)
    plot <- data@plot
    layout <- data@layout
    data <- data@data
    theme <- plot_theme(plot)
  
    geom_grobs <- Map(function(l, d) l$draw_geom(d, layout), plot@layers, data)
  
    facet <- layout$render(geom_grobs, data, theme, plot@labels)
    layout <- facet$layout
    strip_layout <- layout[grepl("^strip", layout$name), 1:4]
    as.list(strip_layout)
  }
  .plot("test-facet-strips.R: facet_wrap() builds correct output #1", p <- ggplot(mtcars, aes(disp, drat)) + geom_point())
  .plot("test-facet-strips.R: facet_wrap() builds correct output #2", wrap <- p + facet_wrap(~cyl))
  wrap_expected <- list(
      t = c(3, 3, 3),
      l = c(3, 7, 11),
      b = c(3, 3, 3),
      r = c(3, 7, 11)
    )
})

