corpus_block("test-facet-strips.R: strip clipping can be set from the theme", {
  strip_layout <- function(p) {
    data <- ggplot_build(p)
    plot <- data@plot
    layout <- data@layout
    data <- data@data
    theme <- plot_theme(plot)
  
    geom_grobs <- Map(function(l, d) l$draw_geom(d, layout), plot@layers, data)
  
    facet <- layout$render(geom_grobs, data, theme, plot@labels)
    layout <- facet$layout
    strip_layout <- layout[grepl("^strip", layout$name), 1:4]
    as.list(strip_layout)
  }
  .plot("test-facet-strips.R: strip clipping can be set from the theme #1", p <- ggplot(mtcars, aes(disp, drat)) + geom_point())
  labels <- data_frame(var1 = "a")
  strip <- render_strips(
      labels,
      labeller = label_value,
      theme = theme_test() + theme(strip.clip = "on")
    )
  strip <- render_strips(
      labels,
      labeller = label_value,
      theme = theme_test() + theme(strip.clip = "off")
    )
})

